create extension if not exists pgcrypto;
create type public.org_role as enum ('owner','admin','advisor','athlete');
create type public.pipeline_stage as enum ('Researching','Target','Contacted','Engaged','Recruiting Interest','High Interest','Visit/Camp','Decision','Committed');
create type public.reminder_status as enum ('open','completed','snoozed','overdue');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,email text,avatar_url text,created_at timestamptz default now());
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,created_by uuid references auth.users(id),created_at timestamptz default now());
create table public.organization_members(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role public.org_role not null,status text default 'active',unique(organization_id,user_id));
create table public.teams(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,created_at timestamptz default now());
create table public.team_members(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.teams(id) on delete cascade,athlete_user_id uuid not null references auth.users(id) on delete cascade,unique(team_id,athlete_user_id));
create table public.athlete_advisor_assignments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,athlete_user_id uuid not null references auth.users(id) on delete cascade,advisor_user_id uuid not null references auth.users(id) on delete cascade,unique(athlete_user_id,advisor_user_id));
create table public.athlete_profiles(user_id uuid primary key references auth.users(id) on delete cascade,grad_year int,positions text[],school text,gpa numeric,interested_majors text[],created_at timestamptz default now());
create table public.colleges(id uuid primary key default gen_random_uuid(),name text unique not null,state text,city text,division text,conference text,website text,created_at timestamptz default now());
create table public.athlete_colleges(id uuid primary key default gen_random_uuid(),athlete_user_id uuid not null references auth.users(id) on delete cascade,college_id uuid not null references public.colleges(id) on delete cascade,status public.pipeline_stage default 'Researching',fit_rating int check(fit_rating between 1 and 5),notes text,created_at timestamptz default now(),unique(athlete_user_id,college_id));
create table public.college_coaches(id uuid primary key default gen_random_uuid(),college_id uuid not null references public.colleges(id) on delete cascade,first_name text,last_name text,title text,email text,phone text,website text,created_at timestamptz default now());
create table public.athlete_coaches(id uuid primary key default gen_random_uuid(),athlete_user_id uuid not null references auth.users(id) on delete cascade,coach_id uuid not null references public.college_coaches(id) on delete cascade,relationship_score int check(relationship_score between 1 and 5),next_step text,last_contact_date date,notes text,created_at timestamptz default now(),unique(athlete_user_id,coach_id));
create table public.interactions(id uuid primary key default gen_random_uuid(),athlete_user_id uuid not null references auth.users(id) on delete cascade,actor_user_id uuid references auth.users(id),college_id uuid references public.colleges(id) on delete set null,coach_id uuid references public.college_coaches(id) on delete set null,type text not null,initiated_by text,date date default current_date,note text,created_at timestamptz default now());
create table public.reminders(id uuid primary key default gen_random_uuid(),owner_user_id uuid not null references auth.users(id) on delete cascade,athlete_user_id uuid references auth.users(id) on delete cascade,college_id uuid references public.colleges(id) on delete cascade,coach_id uuid references public.college_coaches(id) on delete set null,title text not null,due_date date not null,status public.reminder_status default 'open',created_at timestamptz default now());
create table public.events(id uuid primary key default gen_random_uuid(),college_id uuid references public.colleges(id) on delete set null,name text not null,type text,date date,location text,registration_url text,cost numeric,coaches_expected text,created_at timestamptz default now());
create table public.athlete_events(id uuid primary key default gen_random_uuid(),athlete_user_id uuid references auth.users(id) on delete cascade,event_id uuid references public.events(id) on delete cascade,status text,notes text,unique(athlete_user_id,event_id));
create table public.questionnaires(id uuid primary key default gen_random_uuid(),athlete_user_id uuid references auth.users(id) on delete cascade,college_id uuid references public.colleges(id) on delete cascade,sent_date date,completed_date date,status text,notes text);
create table public.notes(id uuid primary key default gen_random_uuid(),athlete_user_id uuid references auth.users(id) on delete cascade,author_user_id uuid references auth.users(id) on delete cascade,visibility text default 'athlete_and_author',content text not null,created_at timestamptz default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,title text,body text,read_at timestamptz,created_at timestamptz default now());
create table public.audit_log(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,actor_user_id uuid references auth.users(id),action text,entity_type text,entity_id uuid,metadata jsonb,created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email) on conflict(id) do update set full_name=excluded.full_name,email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_org_member(org uuid) returns boolean language sql security definer stable as $$ select exists(select 1 from public.organization_members where organization_id=org and user_id=auth.uid() and status='active'); $$;
create or replace function public.can_access_athlete(a uuid) returns boolean language sql security definer stable as $$ select a=auth.uid() or exists(select 1 from public.athlete_advisor_assignments aa where aa.athlete_user_id=a and aa.advisor_user_id=auth.uid()) or exists(select 1 from public.organization_members me join public.organization_members athlete on athlete.organization_id=me.organization_id where me.user_id=auth.uid() and me.status='active' and athlete.user_id=a and me.role in ('owner','admin')); $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','athlete_profiles','colleges','athlete_colleges','college_coaches','athlete_coaches','interactions','reminders','events','athlete_events','questionnaires','notes','notifications','organizations','organization_members','teams','team_members','athlete_advisor_assignments','audit_log'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
create policy "profiles own" on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy "athlete profile access" on public.athlete_profiles for all using(public.can_access_athlete(user_id)) with check(user_id=auth.uid() or public.can_access_athlete(user_id));
create policy "colleges read" on public.colleges for select using(auth.uid() is not null); create policy "colleges write" on public.colleges for all using(auth.uid() is not null) with check(auth.uid() is not null);
create policy "athlete colleges access" on public.athlete_colleges for all using(public.can_access_athlete(athlete_user_id)) with check(public.can_access_athlete(athlete_user_id));
create policy "coach read" on public.college_coaches for select using(auth.uid() is not null); create policy "coach write" on public.college_coaches for all using(auth.uid() is not null) with check(auth.uid() is not null);
create policy "athlete coaches access" on public.athlete_coaches for all using(public.can_access_athlete(athlete_user_id)) with check(public.can_access_athlete(athlete_user_id));
create policy "interactions access" on public.interactions for all using(public.can_access_athlete(athlete_user_id)) with check(public.can_access_athlete(athlete_user_id));
create policy "reminders access" on public.reminders for all using(owner_user_id=auth.uid() or public.can_access_athlete(athlete_user_id)) with check(owner_user_id=auth.uid() or public.can_access_athlete(athlete_user_id));
create policy "events read" on public.events for select using(auth.uid() is not null); create policy "events write" on public.events for all using(auth.uid() is not null) with check(auth.uid() is not null);
create policy "athlete events" on public.athlete_events for all using(public.can_access_athlete(athlete_user_id)) with check(public.can_access_athlete(athlete_user_id));
create policy "questionnaires access" on public.questionnaires for all using(public.can_access_athlete(athlete_user_id)) with check(public.can_access_athlete(athlete_user_id));
create policy "notes access" on public.notes for all using(public.can_access_athlete(athlete_user_id)) with check(public.can_access_athlete(athlete_user_id));
create policy "notifications own" on public.notifications for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "org own membership" on public.organization_members for select using(user_id=auth.uid() or public.is_org_member(organization_id));
create policy "org read" on public.organizations for select using(public.is_org_member(id));
create policy "teams access" on public.teams for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy "team members" on public.team_members for all using(exists(select 1 from public.teams t where t.id=team_id and public.is_org_member(t.organization_id))) with check(exists(select 1 from public.teams t where t.id=team_id and public.is_org_member(t.organization_id)));
create policy "assignments access" on public.athlete_advisor_assignments for all using(athlete_user_id=auth.uid() or advisor_user_id=auth.uid() or exists(select 1 from public.organization_members om where om.user_id=auth.uid() and om.organization_id=athlete_advisor_assignments.organization_id and om.role in ('owner','admin'))) with check(athlete_user_id=auth.uid() or advisor_user_id=auth.uid() or exists(select 1 from public.organization_members om where om.user_id=auth.uid() and om.organization_id=athlete_advisor_assignments.organization_id and om.role in ('owner','admin')));
create policy "audit org" on public.audit_log for select using(organization_id is null or public.is_org_member(organization_id));
